export const getHDIColor = (hdi) => {
  if (hdi >= 0.800) return "#22c55e";
  if (hdi >= 0.700) return "#84cc16";
  if (hdi >= 0.550) return "#eab308";
  if (hdi >= 0.400) return "#f97316";
  return "#ef4444";
};

export const getHDILabel = (hdi) => {
  if (hdi >= 0.800) return "Very High";
  if (hdi >= 0.700) return "High";
  if (hdi >= 0.550) return "Medium";
  if (hdi >= 0.400) return "Low";
  return "Very Low";
};

export const getStatusColor = (status) => {
  const map = { "Developed": "bg-green-100 text-green-800", "Emerging": "bg-blue-100 text-blue-800", "Developing": "bg-yellow-100 text-yellow-800", "Least Developed": "bg-red-100 text-red-800" };
  return map[status] || "bg-gray-100 text-gray-800";
};

export const formatNumber = (num) => {
  if (num >= 1e9) return `${(num / 1e9).toFixed(1)}B`;
  if (num >= 1e6) return `${(num / 1e6).toFixed(1)}M`;
  if (num >= 1e3) return `${(num / 1e3).toFixed(1)}K`;
  return num?.toString() || "N/A";
};